def json_diff(a, b):
    result = {}
    all_keys = set(a.keys()) | set(b.keys())
    for key in all_keys:
        val_a = a.get(key) if key in a else None
        val_b = b.get(key) if key in b else None
        if val_a != val_b:
            result[key] = [val_a, val_b]
    return result
